# pod_leadcond_launch.sh : generated by mk_pod_leadcond.py. Runs ON THE POD (bash -s). Starts chain leadcond_a (six fine-tunes of 6,000 steps, card PREREG_V8F_PROOF_ADD35)
# and the rule-rollout queue LCA (LFTRL) behind it. Each arm passes its own gate token in the chain.
set -u
W=/workspace/v8proof; cd $W/chain2 || exit 1
[ -e $W/chains/leadcond_a ] && { echo 'LAUNCH-NOT-RUN: chains/leadcond_a exists'; exit 1; }
[ -e $W/distrule/rtrule_LCA_queue.log ] && { echo 'LAUNCH-NOT-RUN: queue LCA exists'; exit 1; }
[ -f $W/chains/ruledose_a/ruledose_a_DONE.txt ] || { echo 'LAUNCH-NOT-RUN: predecessor marker absent'; exit 1; }
n=$(nvidia-smi --query-compute-apps=pid --format=csv,noheader 2>/dev/null | grep -c .); [ "${n:-0}" -lt 3 ] || { echo "LAUNCH-NOT-RUN: $n GPU jobs running"; exit 1; }
a=$(grep -E '^anon ' /sys/fs/cgroup/memory.stat | cut -d' ' -f2); m=$(cat /sys/fs/cgroup/memory.max); [ $((m - a)) -gt 20000000000 ] || { echo 'LAUNCH-NOT-RUN: less than 20 GB of the memory limit free'; exit 1; }
echo "LAUNCH-RAN $(date -u +%Y-%m-%dT%H:%M:%SZ) with $n GPU jobs before, anon $a"
C2_CARD=PREREG_V8F_PROOF_ADD35 C2_WAIT_FOR=$W/chains/ruledose_a/ruledose_a_DONE.txt C2_IDLE_MIB=30000 nohup setsid bash chain_arms_ft6.sh leadcond_a arms_leadcond_a.txt > $W/chains/leadcond_a_launch.out 2>&1 < /dev/null &
sleep 2; cd $W/distrule || exit 1
nohup setsid bash pod_rtrule_generic.sh LCA leadcond_a LFTRL_s0:LFT_s0 LFTRL_s1:LFT_s1 > $W/distrule/rtrule_LCA_launch.out 2>&1 < /dev/null &
sleep 50
echo "chain processes: $(pgrep -f '[c]hain_arms_ft6.sh leadcond_a' | wc -l) ; queue processes: $(pgrep -f '[p]od_rtrule_generic.sh LCA' | wc -l) ; trainers: $(pgrep -f '[v]8f_mini_train.py' | wc -l)"
tail -n 4 $W/chains/leadcond_a_launch.out 2>/dev/null | cut -c1-260; tail -n 1 $W/distrule/rtrule_LCA_launch.out 2>/dev/null | cut -c1-200
nvidia-smi --query-compute-apps=pid,used_memory --format=csv,noheader | tr '\n' ';'; echo; grep -E '^anon ' /sys/fs/cgroup/memory.stat
